package com.rustyvault;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

public class SafeCustomerDirectory implements CustomerDirectory {

    private static final Pattern DIGITS_1_18 = Pattern.compile("\\d{1,18}");
    private static final String COLUMNS = "id, name, city, balance_cents";
    private static final String SELECT_ALL = "SELECT " + COLUMNS + " FROM customer";

    private final Connection conn;

    public SafeCustomerDirectory(Connection conn) {
        this.conn = conn;
    }

    @Override
    public long addCustomer(String name, String city, long balanceCents) {
        validateName(name);
        validateName(city);
        if (balanceCents < 0) {
            throw new IllegalArgumentException("INVALID CUSTOMER");
        }
        String sql = "INSERT INTO customer (name, city, balance_cents) VALUES (?, ?, ?)";
        try (PreparedStatement ps = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, name);
            ps.setString(2, city);
            ps.setLong(3, balanceCents);
            ps.executeUpdate();
            try (ResultSet keys = ps.getGeneratedKeys()) {
                keys.next();
                return keys.getLong(1);
            }
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    @Override
    public List<String> findByName(String name) {
        if (name == null) {
            throw new IllegalArgumentException("INVALID NAME");
        }
        return query(SELECT_ALL + " WHERE name = ? ORDER BY id", ps -> ps.setString(1, name));
    }

    @Override
    public List<String> searchByNamePrefix(String prefix) {
        if (prefix == null) {
            throw new IllegalArgumentException("INVALID PREFIX");
        }
        // Escape % and _ for LIKE, using \ as escape character
        String pattern = prefix.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_") + "%";
        return query(SELECT_ALL + " WHERE UPPER(name) LIKE UPPER(?) ESCAPE '\\' ORDER BY id",
                ps -> ps.setString(1, pattern));
    }

    @Override
    public List<String> list(String sortBy, boolean descending) {
        String column = validateSortKey(sortBy);
        String direction = descending ? "DESC" : "ASC";
        String sql = SELECT_ALL + " ORDER BY " + column + " " + direction + ", id ASC";
        return query(sql, ps -> {});
    }

    @Override
    public String getById(String id) {
        validateId(id);
        List<String> rows = query(SELECT_ALL + " WHERE id = ?", ps -> ps.setLong(1, Long.parseLong(id)));
        return rows.isEmpty() ? null : rows.get(0);
    }

    @Override
    public List<String> findByIds(List<String> ids) {
        if (ids == null) {
            throw new IllegalArgumentException("INVALID ID LIST");
        }
        if (ids.isEmpty()) {
            return List.of();
        }
        for (String id : ids) {
            validateId(id);
        }
        // Build placeholders
        StringBuilder placeholders = new StringBuilder();
        for (int i = 0; i < ids.size(); i++) {
            if (i > 0) placeholders.append(",");
            placeholders.append("?");
        }
        String sql = SELECT_ALL + " WHERE id IN (" + placeholders + ") ORDER BY id";
        return query(sql, ps -> {
            for (int i = 0; i < ids.size(); i++) {
                ps.setLong(i + 1, Long.parseLong(ids.get(i)));
            }
        });
    }

    @Override
    public List<String> richerThan(String minBalanceCents) {
        validateAmount(minBalanceCents);
        return query(SELECT_ALL + " WHERE balance_cents > ? ORDER BY id",
                ps -> ps.setLong(1, Long.parseLong(minBalanceCents)));
    }

    @Override
    public List<String> sameCityAs(String id) {
        validateId(id);
        String row = getById(id);
        if (row == null) {
            throw new IllegalArgumentException("UNKNOWN CUSTOMER: " + id);
        }
        String city = row.split("\\|")[2];
        return query(SELECT_ALL + " WHERE city = ? AND id <> ? ORDER BY id",
                ps -> {
                    ps.setString(1, city);
                    ps.setLong(2, Long.parseLong(id));
                });
    }

    @Override
    public int deleteByCity(String city) {
        if (city == null) {
            throw new IllegalArgumentException("INVALID CITY");
        }
        String sql = "DELETE FROM customer WHERE city = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, city);
            return ps.executeUpdate();
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    @Override
    public int count() {
        try (PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) FROM customer");
             ResultSet rs = ps.executeQuery()) {
            rs.next();
            return rs.getInt(1);
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    private List<String> query(String sql, ParameterSetter setter) {
        List<String> rows = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            setter.set(ps);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    rows.add(rs.getLong(1) + "|" + rs.getString(2) + "|" + rs.getString(3) + "|"
                            + rs.getLong(4));
                }
            }
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
        return rows;
    }

    private void validateId(String id) {
        if (id == null || !DIGITS_1_18.matcher(id).matches()) {
            throw new IllegalArgumentException("INVALID ID");
        }
    }

    private void validateAmount(String amount) {
        if (amount == null || !DIGITS_1_18.matcher(amount).matches()) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
    }

    private void validateName(String name) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("INVALID CUSTOMER");
        }
    }

    private String validateSortKey(String sortBy) {
        return switch (sortBy) {
            case "id" -> "id";
            case "name" -> "name";
            case "city" -> "city";
            case "balance" -> "balance_cents";
            default -> throw new IllegalArgumentException("INVALID SORT KEY");
        };
    }

    @FunctionalInterface
    private interface ParameterSetter {
        void set(PreparedStatement ps) throws SQLException;
    }
}

